public sealed class GroupFrictionTests:MonoBehaviour
{
 public static bool UseAI;static bool booted;static HashSet<KeyCode> keys=new HashSet<KeyCode>();public static bool ReadKey(KeyCode k){return keys.Contains(k);}public static bool ReadDown(KeyCode k){return false;}
 public static void Boot(){if(booted)return;booted=true;ControlBindings.settingsPath=System.IO.Path.Combine(Application.dataPath,"..","group-test.ini");var obj=new GameObject("GroupFrictionTests");DontDestroyOnLoad(obj);obj.AddComponent<GroupFrictionTests>();}
 const BindingFlags SP=BindingFlags.Static|BindingFlags.NonPublic,IP=BindingFlags.Instance|BindingFlags.NonPublic;int checks,failures;Type pt;Component fan,zhao,manager;Rigidbody2D ball;float floor,scale;Button proto;Transform parent;GameObject helper;
 void Check(bool ok,string label){checks++;if(!ok)failures++;Debug.Log("ABILITY "+(ok?"PASS ":"FAIL ")+label);}
 Rigidbody2D Body(Component a){return (Rigidbody2D)pt.GetField("rb").GetValue(a);}
 void Move(Component a,Vector2 position){a.transform.position+=(Vector3)(position-Body(a).position);foreach(var b in a.GetComponentsInChildren<Rigidbody2D>()){b.velocity=Vector2.zero;b.angularVelocity=0f;}Physics2D.SyncTransforms();}
 void Freeze(Component a,bool frozen){foreach(var b in a.GetComponentsInChildren<Rigidbody2D>())b.constraints=frozen?RigidbodyConstraints2D.FreezeAll:RigidbodyConstraints2D.None;}
 void Set(object target,string name,object value){target.GetType().GetField(name,IP).SetValue(target,value);}
 object Get(object target,string name){return target.GetType().GetField(name,IP).GetValue(target);}
 void Invoke(object target,string name,params object[] args){target.GetType().GetMethod(name,IP).Invoke(target,args);}
 Button FindButton(string name){foreach(var b in FindObjectsOfType<Button>())if(b.name==name)return b;return null;}
 IEnumerator Ticks(int count){for(int i=0;i<count;i++)yield return new WaitForFixedUpdate();}
 void Helper(){helper=new GameObject("Test UI",typeof(RectTransform),typeof(Canvas),typeof(CanvasScaler),typeof(GraphicRaycaster));helper.GetComponent<Canvas>().renderMode=RenderMode.ScreenSpaceOverlay;helper.GetComponent<CanvasScaler>().uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;helper.GetComponent<CanvasScaler>().referenceResolution=new Vector2(1280,720);parent=helper.transform;var b=new GameObject("Prototype",typeof(RectTransform),typeof(Image),typeof(Button));b.transform.SetParent(parent,false);var label=new GameObject("Text",typeof(RectTransform),typeof(Text));label.transform.SetParent(b.transform,false);label.GetComponent<Text>().font=Font.CreateDynamicFontFromOSFont(new[]{"Microsoft YaHei","Arial"},22);proto=b.GetComponent<Button>();b.SetActive(false);}
 void CaptureUI(string name){
  var canvas=helper.GetComponent<Canvas>();var mode=canvas.renderMode;var oldCamera=canvas.worldCamera;var go=new GameObject("UI Capture Camera",typeof(Camera));var camera=go.GetComponent<Camera>();camera.transform.position=new Vector3(0,0,-10);camera.orthographic=true;camera.orthographicSize=5;camera.cullingMask=1<<31;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.025f,.05f,.09f);foreach(var tr in helper.GetComponentsInChildren<Transform>(true))tr.gameObject.layer=31;
  var rt=new RenderTexture(1280,720,24);camera.targetTexture=rt;canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=camera;canvas.planeDistance=1;Canvas.ForceUpdateCanvases();camera.Render();var old=RenderTexture.active;RenderTexture.active=rt;var image=new Texture2D(1280,720,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1280,720),0,0);image.Apply();System.IO.File.WriteAllBytes(System.IO.Path.Combine(Application.dataPath,"..",name),image.EncodeToPNG());var pixels=image.GetPixels32();int bright=0;foreach(var pixel in pixels)if(pixel.r>45||pixel.g>45||pixel.b>45)bright++;Check(bright>pixels.Length/10,"rendered UI has real field background and readable content: "+name);
  canvas.renderMode=mode;canvas.worldCamera=oldCamera;camera.targetTexture=null;RenderTexture.active=old;Destroy(image);Destroy(rt);Destroy(go);
 }
 bool NoNumbers(SkillGuidePanel guide){foreach(var t in guide.GetComponentsInChildren<Text>())foreach(char c in t.text)if(char.IsDigit(c)||c=='%')return false;return true;}
 IEnumerator Menu(){
  var main=(Component)typeof(GameAIMod).GetField("menuPanel",SP).GetValue(null);var mainButton=main.GetComponentInChildren<Button>(true);
  typeof(GameAIMod).GetMethod("ChooseStyle",SP).Invoke(null,new object[]{main,mainButton,true});yield return null;
  Check(FindButton("mode_技能介绍")!=null,"special opponent-selection page exposes skill introduction");FindButton("mode_技能介绍").onClick.Invoke();yield return null;FindButton("Guide Back").onClick.Invoke();yield return null;
  typeof(GameAIMod).GetMethod("StartGame",SP).Invoke(null,new object[]{0});yield return null;Check(FindObjectOfType<SkillGroupPanel>()!=null&&GameObject.Find("Fan")==null,"real special-mode start opens loadouts before loading match");FindButton("Group Back").onClick.Invoke();yield return null;
  typeof(GameAIMod).GetMethod("ChooseAbilityStyle",SP).Invoke(null,new object[]{main,mainButton});yield return null;int drawn=AbilityMode.DrawBudget();Check(FindButton("mode_技能介绍")!=null,"ability opponent-selection page exposes skill introduction");FindButton("mode_技能介绍").onClick.Invoke();yield return null;FindButton("Guide Back").onClick.Invoke();yield return null;Check(AbilityMode.LotteryDrawn&&AbilityMode.Budget==drawn,"reading skill introduction preserves the current lottery result");
  var overlay=(GameObject)typeof(GameAIMod).GetField("modeOverlay",SP).GetValue(null);if(overlay!=null)overlay.SetActive(false);
  Helper();PlayerSkills.Enabled=true;AbilityMode.Enabled=false;SkillGroups.Reset(true);bool finished=false,cancelled=false;
  var g=SkillGroupPanel.Open(parent,proto,0,delegate{finished=true;},delegate{cancelled=true;});yield return null;
  Check(FindButton("Group Select 0")!=null&&FindButton("Group Select 1")!=null&&g.GetComponentInChildren<Text>().text=="选择技能组","group title and two clear choices");
  Canvas.ForceUpdateCanvases();yield return new WaitForEndOfFrame();CaptureUI("技能组选择.png");yield return Ticks(3);
  FindButton("Group Select 1").onClick.Invoke();FindButton("Group Confirm").onClick.Invoke();Check(!finished&&SkillGroups.Group(0)==1,"first human chooses defense then second human gets a turn");
  FindButton("Group Select 0").onClick.Invoke();FindButton("Group Back").onClick.Invoke();Check(SkillGroups.Group(0)==1&&SkillGroups.Group(1)==0&&!cancelled,"back navigation preserves both choices");FindButton("Group Confirm").onClick.Invoke();FindButton("Group Confirm").onClick.Invoke();yield return null;Check(finished&&!cancelled,"both humans confirm before match starts");
  SkillGroups.Reset(true);SkillGroups.Set(1,0);SkillGroupPanel.Open(parent,proto,1,delegate{},delegate{});yield return null;FindButton("Group Select 1").onClick.Invoke();FindButton("Group Confirm").onClick.Invoke();yield return null;Check(SkillGroups.Group(0)==1&&SkillGroups.Group(1)==1,"human Fan can choose defense while Zhao AI keeps defense");
  SkillGroups.Reset(true);SkillGroups.Set(0,1);SkillGroupPanel.Open(parent,proto,2,delegate{},delegate{});yield return null;FindButton("Group Select 0").onClick.Invoke();FindButton("Group Confirm").onClick.Invoke();yield return null;Check(SkillGroups.Group(0)==0&&SkillGroups.Group(1)==0,"human Zhao can choose attack while Fan AI keeps attack");
  var guide=SkillGuidePanel.Open(parent,proto);yield return null;Check(guide.GetComponentsInChildren<Text>().Length==26&&NoNumbers(guide),"all twelve skills have concise descriptions without numeric or allocation details");Canvas.ForceUpdateCanvases();yield return new WaitForEndOfFrame();CaptureUI("技能介绍.png");yield return null;FindButton("Guide Back").onClick.Invoke();yield return null;Check(FindObjectOfType<SkillGuidePanel>()==null,"skill introduction returns to preceding page");
  // The network reuses exact fixed loadouts; they do not consume a lottery budget.
  var read=typeof(LanMultiplayer).GetMethod("ReadBuild",SP);AbilityMode.SetBudget(12);var args=new object[]{new[]{"4","4","4",SkillGroups.Attack.ToString()},0,null};bool valid=(bool)read.Invoke(null,args);args=new object[]{new[]{"4","4","4","4095"},0,null};Check(valid&&!(bool)read.Invoke(null,args),"LAN accepts the full attack group and rejects arbitrary extra skills");
  bool ready=false;var lan=SkillGroupPanel.OpenLan(parent,proto,1,delegate{ready=true;},delegate{});yield return null;FindButton("Group Select 1").onClick.Invoke();FindButton("Group Confirm").onClick.Invoke();yield return null;Check(ready&&SkillGroups.Group(1)==1,"LAN player confirms only their owned character");Destroy(helper);yield return null;
 }
 IEnumerator Scene(int style,int fanGroup=0,int zhaoGroup=1){keys.Clear();Time.timeScale=1;SkillGroups.Reset(style==1);AbilityMode.Enabled=style==2;PlayerSkills.Enabled=style==1;AbilityMode.SetBudget(24);if(style==1){SkillGroups.Set(0,fanGroup);SkillGroups.Set(1,zhaoGroup);}else AbilityMode.Reset();
  typeof(GameAIMod).GetMethod("BeginGame",SP).Invoke(null,new object[]{0});yield return new WaitForSeconds(.5f);pt=Type.GetType("PlayerController, Assembly-CSharp");fan=GameObject.Find("Fan").GetComponent(pt);zhao=GameObject.Find("Zhao").GetComponent(pt);manager=FindObjectOfType(pt.Assembly.GetType("GameManager")) as Component;ball=(FindObjectOfType(pt.Assembly.GetType("Ball")) as Component).GetComponent<Rigidbody2D>();floor=GameObject.Find("Down").GetComponent<Collider2D>().bounds.max.y;scale=Mathf.Abs(fan.transform.lossyScale.x)/.8f;ball.position=new Vector2(0,5f);ball.velocity=Vector2.zero;ball.gravityScale=0f;GameAIMod.OnBallReset();yield return Ticks(2);
 }
 bool Mask(Component a,int expected){for(int i=0;i<AbilityMode.Skills.Length;i++)if(SkillRework.Has(a,i)!=((expected&(1<<i))!=0))return false;return true;}
 IEnumerator Groups(){yield return Scene(1,1,0);Check(Mask(fan,SkillGroups.Defense)&&Mask(zhao,SkillGroups.Attack),"swapped groups grant exactly their skills without character-only leftovers");Check(fan.GetComponent<BuildPlayer>()!=null&&zhao.GetComponent<BuildPlayer>()!=null&&fan.GetComponent<PlayerSkills>()==null&&zhao.GetComponent<PlayerSkills>()==null,"fixed groups run one skill implementation per player without duplicate native effects");
  SkillRework.ResetShotTracking();Check(SkillRework.Effective(zhao,0)==4&&SkillRework.Effective(zhao,2)==4&&SkillRework.Effective(fan,0)==4,"attack group has no free kickoff or jumping bonus");Check(AbilityMode.JumpMultiplier(fan)>1f&&AbilityMode.JumpMultiplier(zhao)==1f,"fortress only follows defense group and resilience never buffs jumping");
  // Crown contact launches the purchased cannon for Zhao's attack group.
  Move(zhao,new Vector2(0,Body(zhao).position.y));Move(fan,new Vector2(6,Body(fan).position.y));var head=zhao.transform.Find("Head").GetComponent<Collider2D>();ball.position=new Vector2(head.bounds.center.x,head.bounds.max.y+ball.GetComponent<Collider2D>().bounds.extents.y-.012f*scale);ball.velocity=Vector2.down*.5f;ball.gravityScale=1f;Physics2D.SyncTransforms();PlayerSkills.SetAction((Animator)pt.GetField("anim").GetValue(zhao),"Head",zhao);yield return Ticks(6);var effects=(float[])Get(zhao.GetComponent<BuildPlayer>(),"effects");Check(ball.velocity.x< -3f&&effects[1]>0,"Zhao attack group actually launches cannon header toward Fan's goal");
  yield return Scene(1);Check(Mask(fan,SkillGroups.Attack)&&Mask(zhao,SkillGroups.Defense),"default groups retain existing Fan attack and Zhao defense skills");
  yield return Scene(2);AbilityMode.For(zhao).Purchased=1<<6;Check(!SkillGroups.Configured&&AbilityMode.Has(zhao,6)&&!AbilityMode.Has(fan,6),"ability mode keeps independent purchased skills");yield return Scene(0);Check(!AbilityMode.Runtime&&!SkillRework.Has(fan,1)&&!SkillRework.Has(zhao,6),"classic mode remains without special skills");
 }
 IEnumerator Roll(int style,float sign){yield return Scene(style);Move(fan,new Vector2(-11,Body(fan).position.y));Move(zhao,new Vector2(11,Body(zhao).position.y));Freeze(fan,true);Freeze(zhao,true);var shape=ball.GetComponent<Collider2D>();ball.position=new Vector2(-sign*4f,floor+shape.bounds.extents.y+.005f);ball.gravityScale=1f;ball.velocity=new Vector2(sign*3f,0);ball.angularVelocity=-sign*3f/shape.bounds.extents.y*Mathf.Rad2Deg;float prior=3f;bool monotonic=true,supported=false;
  for(int i=0;i<80;i++){yield return new WaitForFixedUpdate();supported|=shape.IsTouching(GameObject.Find("Down").GetComponent<Collider2D>());float current=Mathf.Abs(ball.velocity.x);if(i>3&&current>prior+.03f)monotonic=false;prior=current;}
  Check(supported&&monotonic&&Mathf.Abs(ball.velocity.x)<1f,"real pitch rolling slows in style="+style+" direction="+sign+" speed="+ball.velocity.x);yield return Ticks(120);Check(Mathf.Abs(ball.velocity.x)<.03f&&Mathf.Abs(ball.angularVelocity)<1f,"coasting ball eventually rests without spin reaccelerating style="+style);
 }
 IEnumerator Air(){yield return Scene(0);Move(fan,new Vector2(-11,Body(fan).position.y));Move(zhao,new Vector2(11,Body(zhao).position.y));Freeze(fan,true);Freeze(zhao,true);ball.position=new Vector2(-3,3);ball.gravityScale=0;ball.drag=0;ball.angularDrag=0;ball.velocity=new Vector2(2f,0);ball.angularVelocity=60f;yield return Ticks(40);Check(Mathf.Abs(ball.velocity.x-2f)<.001f&&Mathf.Abs(ball.angularVelocity-60)<.001f,"pitch resistance never brakes an airborne ball");var friction=ball.GetComponent<PitchFriction>();Time.timeScale=0f;Vector2 before=ball.velocity;Invoke(friction,"FixedUpdate");Check(ball.velocity==before,"pause does not apply friction");Time.timeScale=1f;}
 IEnumerator Rescue(int style,bool left){yield return Scene(style,left?1:0,left?0:1);var actor=left?fan:zhao;var other=left?zhao:fan;float direction=left?1:-1;Move(actor,new Vector2(0,Body(actor).position.y));Move(other,new Vector2(-direction*7f,Body(other).position.y));if(style==2)AbilityMode.For(actor).Purchased=1<<6;
  var owner=actor.GetComponent<BuildPlayer>();ball.position=new Vector2(-direction*1.3f,floor+ball.GetComponent<Collider2D>().bounds.extents.y+.01f);ball.gravityScale=1;ball.velocity=Vector2.right*-direction*1.5f;Physics2D.SyncTransforms();keys.Add(left?KeyCode.A:KeyCode.RightArrow);float begin=Body(actor).position.x,highest=0,cap=(float)pt.GetField("maxVelocity").GetValue(actor)*PlayerMovement.BackwardMultiplier*(left?PlayerMovement.FanRetreatReduction:1)*2;
  for(int i=0;i<100;i++){yield return new WaitForFixedUpdate();highest=Mathf.Max(highest,Body(actor).position.y-floor);}
  keys.Clear();Check((-direction)*(Body(actor).position.x-begin)>.25f,"real low-ball retreat keeps moving rather than remaining rigid style="+style+" actor="+actor.name+" delta="+(Body(actor).position.x-begin));Check((float)Get(owner,"rescueSpeed")<=cap+.02f,"retreat speed cap stays at twice normal style="+style+" actor="+actor.name);
  // A detached rear ball must keep its own momentum during recovery.
  Freeze(actor,true);Move(actor,new Vector2(0,Body(actor).position.y));ball.position=Body(actor).position+new Vector2(-direction*3f,1f);ball.gravityScale=0;ball.velocity=new Vector2(-direction*4f,.5f);ball.angularVelocity=70;Set(owner,"rescueRecover",Time.time+2f);Set(owner,"rescueUntil",-1f);Vector2 incoming=ball.velocity;float spin=ball.angularVelocity;Invoke(owner,"FixedUpdate");Check(Vector2.Distance(ball.velocity,incoming)<.001f&&Mathf.Abs(spin-ball.angularVelocity)<.001f,"recovery never attracts, pins or stops detached rear ball style="+style+" actor="+actor.name);
  // Isolate a genuine rear body overlap before the next physics solve: no scripted velocity cancellation.
  var torso=Body(actor).GetComponent<Collider2D>();var radius=ball.GetComponent<Collider2D>().bounds.extents.x;var edge=torso.ClosestPoint((Vector2)torso.bounds.center+Vector2.right*-direction*3);ball.position=edge+Vector2.right*-direction*(radius-.008f);ball.velocity=Vector2.right*-direction*4f;ball.angularVelocity=-direction*90f;Physics2D.SyncTransforms();incoming=ball.velocity;spin=ball.angularVelocity;Invoke(owner,"FixedUpdate");Check(Vector2.Distance(ball.velocity,incoming)<.001f&&Mathf.Abs(spin-ball.angularVelocity)<.001f,"even rear body contact is not a repeating scripted ball brake style="+style+" actor="+actor.name);
 }
 IEnumerator Start(){Application.runInBackground=true;Application.targetFrameRate=120;QualitySettings.vSyncCount=0;AudioListener.volume=0;Time.captureFramerate=100;yield return new WaitForSeconds(.25f);yield return Menu();yield return Groups();yield return Roll(0,1);yield return Roll(1,-1);yield return Roll(2,1);yield return Air();yield return Rescue(1,false);yield return Rescue(1,true);yield return Rescue(2,false);yield return Rescue(2,true);Debug.Log("ABILITY COMPLETE checks="+checks+" failures="+failures);Application.Quit(failures==0?0:1);}
 void Update(){if(Time.realtimeSinceStartup>145f){Debug.LogError("ABILITY TIMEOUT");Application.Quit(2);}}
}
